CREATE TABLE IF NOT EXISTS order_authorizations (order_id INTEGER PRIMARY KEY REFERENCES orders(id), service_id INTEGER REFERENCES service_catalog(id), unit_price INTEGER NOT NULL CHECK(unit_price>=0), authorized_by INTEGER NOT NULL REFERENCES users(id), authorized_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS charge_pricing (charge_id INTEGER PRIMARY KEY REFERENCES charges(id), amount INTEGER NOT NULL CHECK(amount>=0));
CREATE TABLE IF NOT EXISTS charge_price_history (id INTEGER PRIMARY KEY, charge_id INTEGER NOT NULL REFERENCES charges(id), previous_amount INTEGER NOT NULL, new_amount INTEGER NOT NULL CHECK(new_amount>=0), reason TEXT NOT NULL, changed_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS charge_credits (id INTEGER PRIMARY KEY, charge_id INTEGER NOT NULL REFERENCES charges(id), amount INTEGER NOT NULL CHECK(amount>0), source_id INTEGER NOT NULL UNIQUE, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS adjustment_reversals (adjustment_id INTEGER PRIMARY KEY REFERENCES adjustments(id), reason TEXT NOT NULL, reversed_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS medicine_units (id INTEGER PRIMARY KEY, medicine_id INTEGER NOT NULL REFERENCES medicines(id), name TEXT NOT NULL, base_factor INTEGER NOT NULL CHECK(base_factor>0 AND base_factor<=1000), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), UNIQUE(medicine_id,name));
CREATE TABLE IF NOT EXISTS controlled_approvals (prescription_id INTEGER PRIMARY KEY REFERENCES prescriptions(id), approved_by INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, register_ref TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS controlled_receipts (id INTEGER PRIMARY KEY, medicine_id INTEGER NOT NULL REFERENCES medicines(id), lot_number TEXT NOT NULL, expiry_date TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), register_ref TEXT NOT NULL, reason TEXT NOT NULL, requested_by INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewed_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL, reviewed_at TEXT, request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS controlled_ledger (id INTEGER PRIMARY KEY, medicine_id INTEGER NOT NULL REFERENCES medicines(id), stock_lot_id INTEGER REFERENCES stock_lots(id), event TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), actor_id INTEGER NOT NULL REFERENCES users(id), reviewer_id INTEGER REFERENCES users(id), register_ref TEXT NOT NULL, source_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS medication_returns (id INTEGER PRIMARY KEY, dispensation_id INTEGER NOT NULL REFERENCES dispensations(id), reason TEXT NOT NULL, requested_by INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewed_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL, reviewed_at TEXT, request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS medication_return_items (id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL REFERENCES medication_returns(id), dispensation_item_id INTEGER NOT NULL REFERENCES dispensation_items(id), quantity INTEGER NOT NULL CHECK(quantity>0), UNIQUE(return_id,dispensation_item_id));
CREATE TABLE IF NOT EXISTS clinical_revisions (id INTEGER PRIMARY KEY, visit_id INTEGER NOT NULL REFERENCES visits(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, actor_id INTEGER REFERENCES users(id), reason TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(visit_id,version));
CREATE TABLE IF NOT EXISTS nursing_notes (id INTEGER PRIMARY KEY, visit_id INTEGER NOT NULL REFERENCES visits(id), nurse_id INTEGER NOT NULL REFERENCES users(id), content TEXT NOT NULL, created_at TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS nursing_tasks (id INTEGER PRIMARY KEY, visit_id INTEGER NOT NULL REFERENCES visits(id), nurse_id INTEGER NOT NULL REFERENCES users(id), ordered_by INTEGER NOT NULL REFERENCES users(id), description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','cancelled')), created_at TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS nursing_executions (task_id INTEGER PRIMARY KEY REFERENCES nursing_tasks(id), nurse_id INTEGER NOT NULL REFERENCES users(id), content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nursing_task_cancellations (task_id INTEGER PRIMARY KEY REFERENCES nursing_tasks(id), actor_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prescription_cancellations (prescription_id INTEGER PRIMARY KEY REFERENCES prescriptions(id), actor_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visit_cancellations (visit_id INTEGER PRIMARY KEY REFERENCES visits(id), actor_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_v050_notes_visit ON nursing_notes(visit_id,id);
CREATE INDEX IF NOT EXISTS idx_v050_tasks_visit ON nursing_tasks(visit_id,nurse_id,status);
CREATE INDEX IF NOT EXISTS idx_v050_return_dispense ON medication_returns(dispensation_id,status);
CREATE INDEX IF NOT EXISTS idx_v050_return_items ON medication_return_items(dispensation_item_id);
CREATE INDEX IF NOT EXISTS idx_v050_credits ON charge_credits(charge_id);
CREATE VIEW effective_charges AS SELECT ch.id,ch.visit_id,ch.label,ch.created_at,
CASE WHEN EXISTS(SELECT 1 FROM charge_voids v WHERE v.charge_id=ch.id) THEN 0
ELSE COALESCE((SELECT p.amount FROM charge_pricing p WHERE p.charge_id=ch.id),ch.amount)-COALESCE((SELECT SUM(cr.amount) FROM charge_credits cr WHERE cr.charge_id=ch.id),0) END AS amount,
ch.amount AS original_amount FROM charges ch;
CREATE VIEW effective_adjustments AS SELECT a.* FROM adjustments a WHERE NOT EXISTS(SELECT 1 FROM adjustment_reversals r WHERE r.adjustment_id=a.id);
